fun read(key: String, readTs: Long, limit: Long): ReadResult {
    val all = versionsOf(key)
    all.firstOrNull { !it.committed && it.ts <= limit }
        ?.let { return Blocked(it.txn!!) }                 // may commit below us: wait
    all.filter { it.committed && it.ts > readTs && it.ts <= limit }
        .maxOfOrNull { it.ts }
        ?.let { return Uncertain(it) }                     // can't tell before from after
    val v = all.filter { it.committed && it.ts <= readTs }.maxBy { it.ts }
    return Value(v.value, v.ts)                            // the snapshot at readTs
}
